import React from "react";
import { motion } from "framer-motion";
import { FilePlus2, NotebookPen, ShieldCheck } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";

const StudentDashboard = ({ onNewEntry }) => {
  const actions = [
    {
      id: "new",
      label: "New Diary Entry",
      icon: <FilePlus2 className="w-12 h-12 text-indigo-600" />,
      desc: "Write and save your thoughts securely.",
      action: onNewEntry,
    },
    {
      id: "view",
      label: "View My Entries",
      icon: <NotebookPen className="w-12 h-12 text-purple-600" />,
      desc: "Browse through your previous diary entries.",
      action: () => alert("Viewing entries..."),
    },
    {
      id: "secure",
      label: "Security Settings",
      icon: <ShieldCheck className="w-12 h-12 text-pink-600" />,
      desc: "Manage biometrics, encryption & steganography.",
      action: () => alert("Opening security settings..."),
    },
  ];

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-indigo-700 via-purple-700 to-pink-600 text-white p-6">
      <motion.div
        initial={{ y: 40, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="max-w-5xl w-full text-center space-y-10 bg-white/10 backdrop-blur-lg rounded-2xl p-10 shadow-2xl"
      >
        <h1 className="text-4xl font-extrabold">Student Dashboard</h1>
        <p className="text-lg text-gray-200">
          Welcome back! Manage your diary with security, ease, and style.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {actions.map((item) => (
            <motion.div
              key={item.id}
              whileHover={{ scale: 1.05 }}
              onClick={item.action}
              className="cursor-pointer"
            >
              <Card className="p-6 rounded-2xl shadow-lg hover:ring-2 hover:ring-yellow-400 transition">
                <CardContent className="flex flex-col items-center space-y-4">
                  {item.icon}
                  <h2 className="text-xl font-bold text-gray-800">
                    {item.label}
                  </h2>
                  <p className="text-sm text-gray-600">{item.desc}</p>
                </CardContent>
              </Card>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </div>
  );
};

export default StudentDashboard;
